def solve(record):
    x = record['record_1']
    stack = []
    for part in x.split('/'):
        # Repeated slashes produce empty separators; skip them.
        if part == '':
            continue
        if part == '..':
            # Pop the previous component unless nothing to pop
            # or the previous component is itself an excess '..'.
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                # Preserve excess '..' components.
                stack.append('..')
        else:
            # Single-dot components are appended as literal dot strings.
            # All other components (including multi-dot ones) are kept
            # with their original case.
            stack.append(part)
    return stack
```

